document.addEventListener("DOMContentLoaded",function(){function n(n){return n>=1e6?`$${Math.round(n/1e6)}M`:n>=1e3?`$${Math.round(n/1e3)}K`:n.toLocaleString("en-US",{style:"currency",currency:"USD",minimumFractionDigits:2,maximumFractionDigits:2})}const e=document.getElementById("business-profit-form"),t=document.getElementById("business-profit-result");e&&e.addEventListener("submit",function(e){e.preventDefault();const i=parseFloat(document.getElementById("target-profit").value),o=parseFloat(document.getElementById("business-margin").value);if(i<=0||o<=0||o>=100)return t.textContent="Please enter valid profit and margin values.",void 0;const r=i/(o/100),l=12*r,s=l/52,u=l/365,a=12*i,g=a/52,d=a/365;t.innerHTML=`\n        <h3>Required Sales Volume:</h3>\n        <ul>\n          <li><strong>Monthly Revenue:</strong> ${n(r)}</li>\n          <li><strong>Annual Revenue:</strong> ${n(l)}</li>\n          <li><strong>Weekly Revenue:</strong> ${n(s)}</li>\n          <li><strong>Daily Revenue:</strong> ${n(u)}</li>\n        </ul>\n        <h3>Corresponding Profit:</h3>\n        <ul>\n          <li><strong>Monthly Profit:</strong> ${n(i)}</li>\n          <li><strong>Annual Profit:</strong> ${n(a)}</li>\n          <li><strong>Weekly Profit:</strong> ${n(g)}</li>\n          <li><strong>Daily Profit:</strong> ${n(d)}</li>\n        </ul>\n      `})});